	assert!(f.manager.lookup(tenant(), id(0x7f71)).unwrap().is_none());
	assert!(f.manager.lookup(tenant(), id(0x7f72)).unwrap().is_none());
	assert_eq!(
		std::fs::read(&f.file).unwrap(),
		f.bytes,
		"quarantined L1 evidence must remain"
	);
