async fn b11b_mismatched_commit_digest_refuses_resolution() {
	b11b_bad_proof_refuses(0).await;
}
#[tokio::test]
async fn b11b_mismatched_output_identity_refuses_resolution() {
	b11b_bad_proof_refuses(1).await;
}
